(()=>{'use strict';
if(window.__franklinPolicyLoaded)return;window.__franklinPolicyLoaded=true;
const DISCORD='https://discord.gg/HgcbPjcyJ';
const DEFAULT_LANGUAGE='en';
const DEFAULT_LOCALE='en-US';
try{document.documentElement.lang=DEFAULT_LANGUAGE;}catch{}
const norm=v=>String(v||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9+._-]+/g,' ').replace(/\s+/g,' ').trim();
function piracy(q){const n=norm(q);return /(?:download|get|find|where|send|share).{0,35}(?:game files|game data|full game|rpf files|cracked|pirated|bajakan)/.test(n)||/(?:torrent|warez).{0,30}(?:gta v|game files|game data)/.test(n)}
function englishResult(r){return r&&typeof r==='object'?{...r,language:DEFAULT_LANGUAGE,locale:DEFAULT_LOCALE}:r;}
function piracyResult(){return englishResult({text:"I can help with the port and file layout, but I can't help find or distribute pirated GTA V game data. Use game files from a copy you own. If you need the correct folder structure or installation steps, I can help with that.",topic:'installation',grounded:true,source:{href:'guide.html',label:'Installation Guide'},suggestions:['Where should my game files go?','How do I install the IPA?']});}
function technicalFailure(q){return /\b(crash|crashes|crashing|freeze|frozen|stuck|black screen|force close|loading forever|hang|hung)\b/.test(norm(q))}
function post(q,r){if(!r||!r.text)return englishResult(r);let text=String(r.text).trim();const n=norm(q);if(/\b(fps|frame rate|performance)\b/.test(n)&&/\b\d+(?:\.\d+)?\s*fps\b/i.test(text)&&!/no (?:fps|frame rate).{0,12}guarantee|not guaranteed|no guaranteed fps/i.test(text))text=`There is no guaranteed FPS for any device. ${text}`;if(technicalFailure(q)&&!/gta v\s*>\s*logs|logs folder|whole.*logs|entire.*logs/i.test(text))text+=`\n\nIf the issue continues, send the whole GTA V > Logs folder and include your device model, OS version, build date, signing method, free storage, the exact error, and what you were doing immediately before it happened.`;if(/\b(latest|newest|current|most recent)\b/.test(n)&&/\b(build|release|update|ipa)\b/.test(n)){r={...r,source:r.source||{href:'updates.html',label:'iOS & MacOS Updates'}};}if(/\b(download|get).{0,18}\bipa\b/.test(n)){r={...r,discord:true};if(!/discord/i.test(text))text+=`\n\nThe latest IPA link is handled through the project's Discord rather than being hosted on this site.`;}return englishResult({...r,text});}
function wrap(name){const api=window[name];if(!api||api.__policyWrapped||typeof api.answer!=='function')return false;const old=api.answer.bind(api);api.answer=async q=>{if(piracy(q))return piracyResult();return post(q,await old(q));};api.__policyWrapped=true;api.defaultLanguage=DEFAULT_LANGUAGE;api.defaultLocale=DEFAULT_LOCALE;return true;}
function loadGeneralSupport(){if(window.FranklinGeneralSupport||document.querySelector('script[data-franklin-general-support]'))return;const s=document.createElement('script');s.src='franklin-general-support.js?v=20261030support136b';s.async=true;s.dataset.franklinGeneralSupport='true';s.dataset.language=DEFAULT_LANGUAGE;document.head.append(s);}
loadGeneralSupport();
const names=['FranklinSiteRAG','FranklinExtended','FranklinEngine'];
let tries=0;const timer=setInterval(()=>{let all=true;for(const n of names)if(!wrap(n))all=false;if(all||++tries>120)clearInterval(timer)},50);
window.FranklinPolicy={defaultLanguage:DEFAULT_LANGUAGE,defaultLocale:DEFAULT_LOCALE,forceEnglish:true,discord:DISCORD,post,piracy,englishResult,status:()=>({defaultLanguage:DEFAULT_LANGUAGE,defaultLocale:DEFAULT_LOCALE,forceEnglish:true,rules:['english-default','no-piracy','no-guaranteed-fps','full-logs-for-crash','fresh-build-routing','general-support-loader']})};
})();